// UpdateUsername is the resolver for the updateUsername field.
func (r *mutationResolver) UpdateUsername(ctx context.Context, input model.UpdateUsernameInput) (*model.UpdateUsernameResult, error) {
	uid, err := requireUser(ctx)
	if err != nil {
		return nil, err
	}

	newUsername := strings.TrimSpace(input.NewUsername)
	if newUsername == "" {
		return nil, fmt.Errorf("new username is required")
	}
	if len(newUsername) < 3 {
		return nil, fmt.Errorf("username must be at least 3 characters long")
	}
	// Parity with the REST contract: a rename requires proof of the current
	// password, so a stolen access token alone cannot take over an account.
	if input.Password == nil || *input.Password == "" {
		return nil, fmt.Errorf("password is required to change username")
	}
	user, err := db.GetUserByID(ctx, r.DB, uid)
	if err != nil {
		return nil, err
	}
	if user == nil || !user.PasswordHash.Valid || !auth.CheckPassword(user.PasswordHash.String, *input.Password) {
		return nil, fmt.Errorf("password is incorrect")
	}

	exists, _ := db.UserExists(ctx, r.DB, newUsername)
	if exists {
		return nil, fmt.Errorf("username already taken")
	}

	if err := db.UpdateUsername(ctx, r.DB, uid, newUsername); err != nil {
		return nil, err
	}
	// Parity with REST: re-issue JWTs so the client's stored token carries the
	// new username claim.
	newToken, newRefresh, err := auth.GenerateTokens(uid, newUsername, user.Role, user.TokenVersion)
	if err != nil {
		return nil, err
	}
	return &model.UpdateUsernameResult{
		Success:      true,
		Message:      strPtr("Username updated successfully"),
		Username:     strPtr(newUsername),
		Token:        strPtr(newToken),
		RefreshToken: strPtr(newRefresh),
	}, nil
}

