// DeleteImages is the resolver for the deleteImages field.
func (r *mutationResolver) DeleteImages(ctx context.Context, images []*model.DeleteImageInput) (*model.DeleteImagesResult, error) {
	uid, err := requireUser(ctx)
	if err != nil {
		return nil, err
	}
	if len(images) == 0 {
		return &model.DeleteImagesResult{Success: false, Deleted: 0, Results: []*model.DeleteImageResult{}}, nil
	}

	// Deduplicate by id+runnerId (runner-backed deletion only).
	type dedupeKey struct {
		id       string
		runnerID string
	}
	seen := make(map[dedupeKey]bool)
	unique := make([]*model.DeleteImageInput, 0, len(images))
	for _, img := range images {
		source := ""
		if img.RunnerID != nil {
			source = *img.RunnerID
		}
		key := dedupeKey{id: img.ID, runnerID: source}
		if seen[key] {
			continue
		}
		seen[key] = true
		unique = append(unique, img)
	}

	runners, err := db.GetAllRunners(ctx, r.DB, uid)
	if err != nil {
		return nil, err
	}
	runnerMap := make(map[int64]db.RunnerRow, len(runners))
	for _, rr := range runners {
		runnerMap[rr.ID] = rr
	}

	outcomes := make([]*model.DeleteImageResult, len(unique))
	var wg sync.WaitGroup
	for i, img := range unique {
		wg.Add(1)
		go func(i int, img *model.DeleteImageInput) {
			defer wg.Done()
			outcomes[i] = r.deleteOneImage(ctx, img, runnerMap)
		}(i, img)
	}
	wg.Wait()

	results := make([]*model.DeleteImageResult, 0, len(outcomes))
	var errs []*model.DeleteImageResult
	for _, o := range outcomes {
		if o.Error != nil {
			errs = append(errs, o)
		} else {
			results = append(results, o)
		}
	}
	res := &model.DeleteImagesResult{Success: true, Deleted: len(results), Results: results}
	if len(errs) > 0 {
		res.Errors = errs
	}
	return res, nil
}

