// TriggerIntent is the resolver for the triggerIntent field.
func (r *mutationResolver) TriggerIntent(ctx context.Context, id string, idempotencyKey *string) (*model.IntentExecution, error) {
	uid, err := requireUser(ctx)
	if err != nil {
		return nil, err
	}
	iid, _ := strconv.ParseInt(id, 10, 64)

	intent, err := db.GetIntentByID(ctx, r.DB, iid, uid)
	if err != nil || intent == nil {
		return nil, fmt.Errorf("intent not found")
	}
	if err := claimIdempotency(ctx, r.DB, uid, "trigger-intent:"+id, idempotencyKey); err != nil {
		return nil, err
	}

	// Pre-create the 'pending' row so the client gets the execution id
	// synchronously; the intent executor adopts it (the evaluator path lets
	// the executor create its own 'running' row instead).
	execID, err := db.CreateIntentExecution(ctx, r.DB, iid, uid, "manual")
	if err != nil {
		releaseIdempotency(ctx, r.DB, uid, "trigger-intent:"+id, idempotencyKey)
		return nil, fmt.Errorf("create execution: %w", err)
	}

	// Fire-and-forget through the shared intents engine: live matching,
	// stack-aware concurrency, upgrade locks, Discord notification.
	exec := r.intentsExecutor()
	execIDA := execID
	intentCopy := *intent
	go func() {
		runCtx := context.Background()
		if _, err := exec.ExecuteIntent(runCtx, &intentCopy, uid, intents.ExecOptions{
			TriggerType: "manual",
			ExecutionID: &execIDA,
		}); err != nil {
			// Deliberately keep the idempotency claim once the execution row
			// exists: the run may have already upgraded some containers before
			// failing, and releasing the key would let a retry double-fire the
			// same intent.
			slog.Error("manual intent execution failed", "intentId", id, "userId", uid, "error", err.Error())
		}
	}()

	return &model.IntentExecution{
		ID:          strconv.FormatInt(execID, 10),
		IntentID:    id,
		Status:      model.IntentExecutionStatusPending,
		TriggerType: model.IntentTriggerTypeManual,
		QueuedAt:    time.Now(),
	}, nil
}

// DryRunIntent is the resolver for the dryRunIntent field.
func (r *mutationResolver) DryRunIntent(ctx context.Context, id string) (*model.IntentExecution, error) {
	uid, err := requireUser(ctx)
	if err != nil {
		return nil, err
	}
	iid, _ := strconv.ParseInt(id, 10, 64)

	intent, err := db.GetIntentByID(ctx, r.DB, iid, uid)
	if err != nil || intent == nil {
		return nil, fmt.Errorf("intent not found")
	}

	// Node parity: dryRunIntent is executeIntent with dryRun forced true —
	// live matching, dry_run rows recorded, no upstream mutation. Synchronous
	// so the client receives the completed execution directly.
	dry := true
	result, err := r.intentsExecutor().ExecuteIntent(ctx, intent, uid, intents.ExecOptions{
		TriggerType: "manual",
		DryRun:      &dry,
	})
	if err != nil {
		return nil, err
	}

	row, _ := db.GetIntentExecutionByID(ctx, r.DB, result.ExecutionID, uid)
	if row == nil {
		return nil, fmt.Errorf("execution not found")
	}
	return intentExecutionToModel(*row), nil
}

