// TriggerBatchJob is the resolver for the triggerBatchJob field.
func (r *mutationResolver) TriggerBatchJob(ctx context.Context, jobType *model.BatchJobType, idempotencyKey *string) (*model.BatchRun, error) {
	uid, err := requireUser(ctx)
	if err != nil {
		return nil, err
	}

	jt := "docker-hub-pull"
	if jobType != nil {
		jt = dbEnumValue(string(*jobType))
	}
	// tracked-apps-check and app-version-scan are Go-owned batch jobs;
	// container inventory sync (docker-hub-pull) goes through pullContainers
	// and the remaining job types have no Go implementation.
	var acquire func(context.Context, int64, bool) (int64, error)
	var execute func(context.Context, int64, int64) error
	switch jt {
	case "tracked-apps-check":
		if r.Sync == nil {
			return nil, fmt.Errorf("tracked-app checks are unavailable")
		}
		acquire, execute = r.Sync.TrackedAcquire, r.Sync.TrackedExecuteAndComplete
	case "app-version-scan":
		if r.Sync == nil {
			return nil, fmt.Errorf("app version scans are unavailable")
		}
		acquire, execute = r.Sync.AppVersionAcquire, r.Sync.AppVersionExecuteAndComplete
	default:
		return nil, fmt.Errorf("batch job %s is not supported by the Go API", jt)
	}
	if err := claimIdempotency(ctx, r.DB, uid, "trigger-batch-job", idempotencyKey); err != nil {
		return nil, err
	}

	// Same guard stack as Node's BatchManager.executeJob: the 'running'
	// batch_run row is created synchronously, the scan runs async.
	batchID, err := acquire(ctx, uid, true)
	if err != nil {
		releaseIdempotency(ctx, r.DB, uid, "trigger-batch-job", idempotencyKey)
		return nil, err
	}

	go func() {
		if err := execute(context.WithoutCancel(ctx), uid, batchID); err != nil {
			slog.Error("manual batch scan failed", "jobType", jt, "userId", uid, "runId", batchID, "error", err)
		}
	}()

	return &model.BatchRun{
		ID:       strconv.FormatInt(batchID, 10),
		Status:   model.BatchRunStatusRunning,
		JobType:  model.BatchJobType(enumConst(jt)),
		QueuedAt: time.Now(),
		IsManual: true,
	}, nil
}

// SetBatchLogLevel is the resolver for the setBatchLogLevel field.
func (r *mutationResolver) SetBatchLogLevel(ctx context.Context, logLevel model.LogLevel) (*model.SuccessResult, error) {
	_, err := requireAdmin(ctx, r.DB)
	if err != nil {
		return nil, err
	}
	level := strings.ToLower(string(logLevel))
	if level != "info" && level != "debug" {
		return nil, fmt.Errorf("log level must be INFO or DEBUG")
	}
	// Node owns this as a system-wide setting: user_id=0, key=log_level,
	// lowercase value. Writing a per-user batch_log_level was a no-op to Node.
	_, err = r.DB.ExecContext(ctx,
		`INSERT INTO settings (user_id, key, value) VALUES (0, 'log_level', ?)
		 ON CONFLICT(user_id, key) DO UPDATE SET value = excluded.value`,
		level)
	if err != nil {
		return nil, err
	}
	return &model.SuccessResult{Success: true}, nil
}

