func (r *queryResolver) OauthProviders(ctx context.Context) ([]*model.OAuthProvider, error) {
	rows, err := db.GetEnabledOAuthProviders(ctx, r.DB)
	if err != nil {
		return nil, err
	}
	opt := func(s string) *string {
		if s == "" {
			return nil
		}
		return &s
	}
	out := make([]*model.OAuthProvider, len(rows))
	for i, row := range rows {
		name := row.DisplayName
		if name == "" {
			name = row.Name
		}
		out[i] = &model.OAuthProvider{
			ID:        strconv.FormatInt(row.ID, 10),
			Name:      name,
			Type:      model.OAuthProviderType(enumConst(row.ProviderType)),
			Enabled:   row.Enabled == 1,
			IssuerURL: opt(row.IssuerURL),
			ClientID:  opt(row.ClientID),
			Scopes:    opt(row.Scopes),
			CreatedAt: parseTime(row.CreatedAt),
			UpdatedAt: parseTime(row.UpdatedAt),
		}
	}
	return out, nil
}

// Logs is the resolver for the logs field.
func (r *queryResolver) Logs(ctx context.Context, lines *int, since *int, file *string, offset *int) (*model.LogResult, error) {
	// Admin-only: Node exposed log files solely through the admin-gated debug
	// controller; the GraphQL surface must not be weaker than that gate.
	if _, err := requireAdmin(ctx, r.DB); err != nil {
		return nil, err
	}

	// Node parity: LOGS_DIR env (default: ./logs relative to the app root),
	// default file combined.log, basename-only sanitization.
	logsDir := os.Getenv("LOGS_DIR")
	if logsDir == "" {
		logsDir = "logs"
	}
	name := "combined.log"
	if file != nil && *file != "" {
		name = filepath.Base(*file)
		if name == "." || name == ".." || strings.ContainsAny(name, `/\`) {
			return nil, fmt.Errorf("invalid log file name")
		}
	}
	logFile := filepath.Join(logsDir, name)

	maxLines := 500
	if lines != nil && *lines > 0 {
		maxLines = *lines
	}

	if st, err := os.Stat(logsDir); err != nil || !st.IsDir() {
		return &model.LogResult{
			Logs: "Logs directory not found: " + logsDir +
				"\n\nLogs will appear here once the application starts generating log entries.",
			TotalLines: 0, ReturnedLines: 0, NewLines: 0, FileSize: 0, Rotated: false,
		}, nil
	}
	if _, err := os.Stat(logFile); err != nil {
		return &model.LogResult{
			Logs: fmt.Sprintf("Log file %s not found in %s.\n\nLogs will appear here once the application starts generating log entries.",
				name, logsDir),
			TotalLines: 0, ReturnedLines: 0, NewLines: 0, FileSize: 0, Rotated: false,
		}, nil
	}

	// Incremental fetch: only return new bytes since the client's offset.
	if offset != nil && *offset >= 0 {
		content, size, err := readFromOffset(logFile, int64(*offset))
		if err != nil {
			return nil, err
		}
		if content == "" && size < int64(*offset) {
			// Log rotated (file shrank below the offset) — signal the client to reload.
			return &model.LogResult{
				Logs: "", TotalLines: 0, ReturnedLines: 0, NewLines: 0, FileSize: int(size), Rotated: true,
			}, nil
		}
		newLines := 0
		for _, l := range strings.Split(content, "\n") {
			if strings.TrimSpace(l) != "" {
				newLines++
			}
		}
		return &model.LogResult{
			Logs: content, TotalLines: 0, ReturnedLines: newLines, NewLines: newLines,
			FileSize: int(size), Rotated: false,
		}, nil
	}

	// Full tail fetch: last N lines.
	tailed, size, err := tailFileLines(logFile, maxLines)
	if err != nil {
		return nil, err
	}
	return &model.LogResult{
		Logs: tailed, TotalLines: 0, ReturnedLines: len(strings.Split(tailed, "\n")), NewLines: 0,
		FileSize: int(size), Rotated: false,
	}, nil
}

// Operation is the resolver for the operation field.
func (r *queryResolver) Operation(ctx context.Context, id string) (*model.Operation, error) {
	uid, err := requireUser(ctx)
	if err != nil {
		return nil, err
	}
	// Batch operations are persisted in batch_runs and can be polled by id
	// (batchUpgrade returns "batch-<runID>"). Single-container pull/upgrade
	// operations are ephemeral with no backing table, so those stay not-found.
	if strings.HasPrefix(id, "batch-") {
		if n, perr := strconv.ParseInt(strings.TrimPrefix(id, "batch-"), 10, 64); perr == nil {
			run, gerr := db.GetBatchRunByID(ctx, r.DB, n, uid)
			if gerr != nil {
				return nil, gerr
			}
			if run != nil {
				return batchRunToOperation(run), nil
			}
		}
	}
	return nil, fmt.Errorf("operation not found or already completed")
}

// SummaryStats is the resolver for the summaryStats field.
func (r *queryResolver) SummaryStats(ctx context.Context) (*model.SummaryStats, error) {
	uid, err := requireUser(ctx)
	if err != nil {
		return nil, err
	}

	var totalContainers, totalRunners, totalTrackedApps int
	r.DB.QueryRowContext(ctx, "SELECT COUNT(*) FROM containers WHERE user_id = ?", uid).Scan(&totalContainers)
	r.DB.QueryRowContext(ctx, "SELECT COUNT(*) FROM runners WHERE user_id = ?", uid).Scan(&totalRunners)
	r.DB.QueryRowContext(ctx, "SELECT COUNT(*) FROM tracked_apps WHERE user_id = ?", uid).Scan(&totalTrackedApps)

	// containersWithUpdates must agree with the per-container flags the UI
	// shows (tab badge, update lists): count through the SAME pipeline the
	// containers connection uses — GetContainers + the live runner merge +
	// identity dedup + the SAME containerHasUpdate logic. The standalone
	// SQL compared deploy-time digests (di.image_digest, stale once an
	// image is re-pulled) with a stricter repo/tag join, and inflated the
	// number ~10x on real data (110 vs 10 on prod).
	withUpdates := 0
	if rows, err := db.GetContainers(ctx, r.DB, uid); err == nil {
		rows = r.mergeLiveRunnerContainers(ctx, uid, rows)
		rows = dedupeContainerRows(rows)
		// totalContainers reflects the same live-merged inventory the
		// containers connection reports, not just persisted rows.
		totalContainers = len(rows)
		for i := range rows {
			if db.ContainerHasUpdate(rows[i]) {
				withUpdates++
			}
		}
	}

	// trackedAppsWithUpdates
	var trackedWithUpdates int
	r.DB.QueryRowContext(ctx, "SELECT COUNT(*) FROM tracked_apps WHERE user_id = ? AND has_update = 1", uid).Scan(&trackedWithUpdates)

	// unusedImagesCount
	unusedImages, _ := db.GetUnusedImages(ctx, r.DB, uid)

	return &model.SummaryStats{
		TotalContainers:        totalContainers,
		ContainersWithUpdates:  withUpdates,
		TotalRunners:           totalRunners,
		TotalTrackedApps:       totalTrackedApps,
		TrackedAppsWithUpdates: trackedWithUpdates,
		UnusedImagesCount:      len(unusedImages),
	}, nil
}

